          adultoCarga:       t(lang, `${doseCarga.toFixed(0)} mg EV/IM 12/12h (3 doses = 6 mg/kg)`, `${doseCarga.toFixed(0)} mg EV/IM cada 12h (3 dosis = 6 mg/kg)`),
